format_data:
{
  "header": {
    "columns": [
      {
        "label": "",
        "fields": [
          {
            "label": "Company Logo",
            "fieldname": "linked_field_lxeeuTKm",
            "fieldtype": "Linked Field",
            "show_label": "hide",
            "custom": 1,
            "width": "84px",
            "link_path": "company.company_logo"
          },
          {
            "label": "Spacer",
            "fieldname": "spacer_nCtaGVsw",
            "fieldtype": "Spacer",
            "custom": 1,
            "height": 20
          }
        ]
      }
    ],
    "gap": 0
  },
  "sections": [
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Custom HTML",
              "fieldname": "custom_html_BxUQIJXO",
              "fieldtype": "HTML",
              "html": "<span>{{ frappe.utils.global_date_format(doc.offer_date,format='long') }}</span>\n",
              "custom_style": "text-align:right;\n",
              "custom": 1
            },
            {
              "label": "Spacer",
              "fieldname": "spacer_EIWRGeHV",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 30
            },
            {
              "label": "Text",
              "fieldname": "static_text_XyETeBcR",
              "fieldtype": "Static Text",
              "align": "center",
              "custom_style": "",
              "custom": 1,
              "text": "JOB OFFER LETTER",
              "bold": 1,
              "font_size": 16
            },
            {
              "label": "Spacer",
              "fieldname": "spacer_DwnFoRni",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 20
            }
          ]
        }
      ]
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Letter",
              "fieldname": "custom_html_body",
              "fieldtype": "HTML",
              "html": "<p>Dear {{doc.applicant_name}},</p>\n<p>We are pleased to offer you employment with {{ doc.company }} in the position of <b>{{ doc.designation }}</b>{% if doc.date_of_joining %}, with joining date of {{ frappe.utils.global_date_format(doc.date_of_joining,format=\"medium\") }}{% endif %}. This letter sets out the terms and conditions of our offer in full.</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            }
          ]
        }
      ],
      "padding": {
        "top": 0,
        "right": 0,
        "bottom": 0,
        "left": 0
      }
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Text",
              "fieldname": "static_text_vohDVyxE",
              "fieldtype": "Static Text",
              "custom_style": "margin:10px 0px;",
              "custom": 1,
              "text": "COMPENSATION",
              "bold": 1,
              "font_size": 14
            },
            {
              "label": "CTC Break-up",
              "fieldname": "ctc_breakup",
              "fieldtype": "Table",
              "options": "Job Offer Component",
              "table_columns": [
                {
                  "label": "Fixed Components",
                  "fieldname": "fixed_components",
                  "fieldtype": "Data",
                  "width": 10
                },
                {
                  "label": "Per Cycle",
                  "fieldname": "per_cycle",
                  "fieldtype": "Currency",
                  "options": "currency",
                  "width": 10
                },
                {
                  "label": "Yearly",
                  "fieldname": "yearly",
                  "fieldtype": "Currency",
                  "options": "currency",
                  "width": 10
                }
              ],
              "table_style": "striped",
              "table_bordered": false,
              "table_header": "styled",
              "custom_style": "margin-bottom:10px;\n"
            }
          ]
        }
      ]
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Text",
              "fieldname": "static_text_vohDVyxE_NYDrHJPG",
              "fieldtype": "Static Text",
              "custom_style": "margin:10px 0px;",
              "custom": 1,
              "text": "LEAVE AND HOLIDAYS",
              "bold": 1,
              "font_size": 14
            },
            {
              "label": "Time Off",
              "fieldname": "custom_html_time_off",
              "fieldtype": "HTML",
              "html": "{%- set ns = namespace(total_paid_leaves=0) -%}\n{%- for row in doc.leave_allocations %}\n      {%- set ns.total_paid_leaves = ns.total_paid_leaves + (row.annual_allocation or 0) %}\n{%- endfor %}\n{%- if doc.leave_allocations or doc.total_public_holidays or doc.weekly_off_days %}\n\n\n{%- if doc.weekly_off_days or doc.total_public_holidays %}\n<p>{% if doc.weekly_off_days %}Your weekly off will fall on {{ \" and \".join(doc.weekly_off_days.rsplit(\", \", 1)) }}.{% endif %}{% if doc.total_public_holidays %} You will also be entitled to {{ doc.total_public_holidays }} public holidays in each calendar year.{% endif %}</p>\n{%- endif %}\n{%- if doc.leave_allocations %}\n<p>You will be entitled to a total of {{ns.total_paid_leaves}} leaves in each calendar year, in accordance with the Company's leave policy. The breakdown of leaves is as follows</p>\n{%- endif %}\n{%- endif -%}\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            },
            {
              "label": "",
              "fieldname": "leave_allocations",
              "fieldtype": "Table",
              "options": "Leave Policy Detail",
              "table_columns": [
                {
                  "label": "Leave Type",
                  "fieldname": "leave_type",
                  "fieldtype": "Link",
                  "options": "Leave Type",
                  "width": 15
                },
                {
                  "label": "Annual Allocation",
                  "fieldname": "annual_allocation",
                  "fieldtype": "Float",
                  "width": 5
                }
              ],
              "table_style": "striped",
              "table_bordered": false,
              "table_header": "styled",
              "table_radius": 0,
              "custom_style": ""
            },
            {
              "label": "Time Off",
              "fieldname": "custom_html_time_off_hVCbGKCw",
              "fieldtype": "HTML",
              "html": "{%- if doc.leave_allocations %}\n<p>Allocation of leaves will be pro-rated for employees joining mid year</p>\n{%- endif %}\n\n",
              "custom_style": "color:#808080;\nfont-size:12px;\ntext-align:justify;",
              "custom": 1
            }
          ]
        }
      ]
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Text",
              "fieldname": "static_text_terms",
              "fieldtype": "Static Text",
              "custom_style": "margin:10px 0px;",
              "custom": 1,
              "text": "TERMS OF EMPLOYMENT",
              "bold": 1,
              "font_size": 14
            },
            {
              "label": "Terms of Employment",
              "fieldname": "custom_html_terms",
              "fieldtype": "HTML",
              "html": "{%- macro num(v) -%}{{ v|int if v == v|int else v }}{%- endmacro -%}\n{%- set department = frappe.db.get_value(\"Department\", doc.department, \"department_name\") if doc.department else None -%}\n{%- set manager = frappe.db.get_value(\"Employee\", doc.reports_to, \"employee_name\") if doc.reports_to else None -%}\n{%- if department or doc.branch or manager or doc.employment_type or doc.working_hours %}\n<p>{% if department %}You will be part of the {{ department }} department.{% endif %}{% if doc.branch %} Your place of work will be {{ doc.branch }}.{% endif %}{% if manager %} You will report to {{ manager }}.{% endif %}{% if doc.employment_type %} Your employment type will be {{ doc.employment_type }}.{% endif %}{% if doc.working_hours %} Your working hours will be {{ num(doc.working_hours) }} hours per day.{% endif %}</p>\n{%- endif %}\n{%- if doc.probation_period_days %}\n<p>You will be on probation for the first {{ doc.probation_period_days }} days of your employment. {% if doc.notice_period_during_probation %}During probation, either party may end the employment by giving {{ doc.notice_period_during_probation }} days' notice.{% else %}During probation, either party may end the employment without notice.{% endif %}{% if doc.notice_number_of_days %} After confirmation, the notice period will be {{ doc.notice_number_of_days }} days.{% endif %}</p>\n{%- elif doc.notice_number_of_days %}\n<p>Either party may end the employment by giving {{ doc.notice_number_of_days }} days' notice.</p>\n{%- endif %}\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            }
          ]
        }
      ],
      "visible_if": "doc.department or doc.branch or doc.reports_to or doc.employment_type or doc.working_hours or doc.probation_period_days or doc.notice_number_of_days"
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Text",
              "fieldname": "static_text_policies",
              "fieldtype": "Static Text",
              "custom_style": "margin:10px 0px;",
              "custom": 1,
              "text": "EMPLOYMENT POLICIES",
              "bold": 1,
              "font_size": 14
            },
            {
              "label": "Employment Policies",
              "fieldname": "custom_html_policies",
              "fieldtype": "HTML",
              "html": "<p>Your employment will be governed by the policies, rules and procedures of the Company, as amended from time to time. These will be made available to you upon joining, and you will be required to comply with them throughout your employment.</p>\n<p>This offer is made subject to the satisfactory verification of your credentials, references and background, to your submission of the documents we request, and to your furnishing proof of your eligibility to work in the country of employment. We will share the list of documents required before your date of joining.</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            }
          ]
        }
      ]
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Text",
              "fieldname": "static_text_offer_terms",
              "fieldtype": "Static Text",
              "custom_style": "margin:10px 0px;",
              "custom": 1,
              "text": "ADDITIONAL TERMS",
              "bold": 1,
              "font_size": 14
            },
            {
              "label": "",
              "fieldname": "offer_terms",
              "fieldtype": "Table",
              "options": "Job Offer Term",
              "table_columns": [
                {
                  "label": "Offer Term",
                  "fieldname": "offer_term",
                  "fieldtype": "Link",
                  "options": "Offer Term",
                  "width": 30
                },
                {
                  "label": "Value / Description",
                  "fieldname": "value",
                  "fieldtype": "Small Text",
                  "width": 70
                }
              ],
              "table_style": "striped",
              "table_bordered": false,
              "table_header": "styled",
              "custom_style": "margin-bottom:10px;\n"
            }
          ]
        }
      ],
      "visible_if": "doc.offer_terms"
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Text",
              "fieldname": "static_text_acceptance",
              "fieldtype": "Static Text",
              "custom_style": "margin:10px 0px;",
              "custom": 1,
              "text": "ACCEPTANCE",
              "bold": 1,
              "font_size": 14
            },
            {
              "label": "Acceptance",
              "fieldname": "custom_html_acceptance",
              "fieldtype": "HTML",
              "html": "{%- if doc.offer_valid_till %}\n<p>This offer will remain open until <b>{{ frappe.utils.global_date_format(doc.offer_valid_till, format=\"medium\") }}</b>. Please confirm your acceptance in writing on or before that date. If we do not receive your acceptance by then, this offer will lapse.</p>\n{%- else %}\n<p>Please confirm your acceptance of this offer in writing.</p>\n{%- endif %}\n<p>We look forward to welcoming you to {{ doc.company }}.</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            },
            {
              "label": "Spacer",
              "fieldname": "spacer_QuROPYsW",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 30
            },
            {
              "label": "Custom HTML",
              "fieldname": "custom_html_CSNGozOA",
              "fieldtype": "HTML",
              "html": "<p>Sincerely,</p>",
              "custom": 1,
              "custom_style": "text-align:justify;"
            },
            {
              "label": "Signature",
              "fieldname": "signature",
              "fieldtype": "Attach Image",
              "show_label": "hide",
              "width": "200px"
            },
            {
              "label": "Spacer",
              "fieldname": "spacer_XaViauFb",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 10
            },
            {
              "label": "Sign-off",
              "fieldname": "custom_html_signoff",
              "fieldtype": "HTML",
              "html": "{%- set signatory = frappe.db.get_value(\"Employee\", {\"user_id\": doc.owner}, \"employee_name\") or frappe.get_fullname(doc.owner) -%}\n<p>{{ signatory }}<br>{{ doc.company }}</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            }
          ]
        }
      ]
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Divider",
              "fieldname": "divider_accept_rule",
              "fieldtype": "Divider",
              "custom": 1,
              "custom_style": "margin:18px 0 12px;border-bottom-color:#d5dae0;"
            },
            {
              "label": "Text",
              "fieldname": "static_text_accept",
              "fieldtype": "Static Text",
              "custom": 1,
              "text": "DECLARATION OF ACCEPTANCE",
              "bold": 1,
              "font_size": 14,
              "custom_style": "margin:10px 0px;"
            },
            {
              "label": "Declaration",
              "fieldname": "custom_html_accept",
              "fieldtype": "HTML",
              "html": "<p>I have read and understood the terms and conditions set out in this letter, and I accept the offer of employment on the terms stated.</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            }
          ]
        }
      ],
      "keep_together": true
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Spacer",
              "fieldname": "spacer_accept_signature",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 40
            },
            {
              "label": "Divider",
              "fieldname": "divider_accept_signature",
              "fieldtype": "Divider",
              "custom": 1,
              "custom_style": "margin:0 0 4px;border-bottom-color:#1f272e;"
            },
            {
              "label": "Text",
              "fieldname": "static_text_accept_signature",
              "fieldtype": "Static Text",
              "custom": 1,
              "text": "Signature",
              "font_size": 12,
              "custom_style": "color:#6b7681;"
            },
            {
              "label": "Spacer",
              "fieldname": "spacer_accept_name",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 8
            },
            {
              "label": "Applicant Name",
              "fieldname": "applicant_name",
              "fieldtype": "Data",
              "show_label": "hide",
              "font_size": 12,
              "custom_style": "color:#6b7681;"
            }
          ]
        },
        {
          "label": "",
          "fields": [
            {
              "label": "Spacer",
              "fieldname": "spacer_accept_date",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 40
            },
            {
              "label": "Divider",
              "fieldname": "divider_accept_date",
              "fieldtype": "Divider",
              "custom": 1,
              "custom_style": "margin:0 0 4px;border-bottom-color:#1f272e;"
            },
            {
              "label": "Text",
              "fieldname": "static_text_accept_date",
              "fieldtype": "Static Text",
              "custom": 1,
              "text": "Date",
              "font_size": 12,
              "custom_style": "color:#6b7681;"
            }
          ]
        }
      ],
      "gap": 48,
      "keep_together": true
    }
  ],
  "footer": {
    "columns": [
      {
        "label": "",
        "fields": []
      }
    ]
  },
  "letter_head": ""
}
